r"""The ``boardwright`` command.

Boardwright normally runs as a Claude Code plugin: the plugin starts the
server and the server prepares the PC by itself (folders, Altium scripts).
These commands are for checking and repairing by hand.

    boardwright [serve]     start the MCP server on stdio (what the plugin runs)
    boardwright setup       prepare this PC now and show the Altium step
                            (--copilot also registers VS Code Copilot)
    boardwright doctor      check the install and the live Altium link
    boardwright relaunch    start the bridge script in the running Altium
    boardwright remove      remove what setup or Boardwright 1.0 registered
                            (add --data to delete the data folder)
    boardwright info        print versions and folders as JSON
    boardwright engine ...  run an engine subcommand directly (advanced)
"""
from __future__ import annotations

import argparse
import json
import os
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Optional

from . import __version__, engine, paths, prepare

SERVER_KEY = "boardwright"
PLUGIN_NAME = "boardwright"
# Skill links that Boardwright 1.0's setup made in ~/.claude/skills. The
# plugin brings its own skill, so these would show it twice.
OLD_SKILL_LINKS = ("boardwright-schematic", "boardwright-layout")
# Names an earlier, separately registered eda-agent server may use. Two
# servers on one Altium share the bridge and confuse each other.
LEGACY_SERVER_KEYS = ("altium", "eda-agent", "eda-agent-altium")
LEGACY_PLUGINS = ("altium-schematic",)
KEY_ENV_VARS = ("MOUSER_API_KEY", "DIGIKEY_CLIENT_ID", "DIGIKEY_CLIENT_SECRET",
                "NEXAR_ACCESS_TOKEN")


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------

def _python() -> str:
    return str(Path(sys.executable).resolve())


def _server_args() -> list[str]:
    return ["-I", "-m", "boardwright", "serve"]


def _ok(msg: str) -> None:
    print(f"  [ok]   {msg}")


def _warn(msg: str) -> None:
    print(f"  [!]    {msg}")


def _fail(msg: str) -> None:
    print(f"  [FAIL] {msg}")


def _claude_dir() -> Path:
    """Claude Code's config folder (CLAUDE_CONFIG_DIR moves it)."""
    override = os.environ.get("CLAUDE_CONFIG_DIR")
    return Path(override) if override else Path.home() / ".claude"


def _claude_skills_dir() -> Path:
    return _claude_dir() / "skills"


def _vscode_mcp_json() -> Path:
    appdata = os.environ.get("APPDATA") or str(Path.home() / "AppData" / "Roaming")
    return Path(appdata) / "Code" / "User" / "mcp.json"


def _claude_json() -> Path:
    override = os.environ.get("CLAUDE_CONFIG_DIR")
    return Path(override) / ".claude.json" if override else Path.home() / ".claude.json"


def _read_json(path: Path) -> Optional[dict]:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError:
        return {}
    except (OSError, ValueError):
        return None


def _is_link(p: Path) -> bool:
    return p.is_symlink() or (hasattr(os.path, "isjunction") and os.path.isjunction(p))


def _enabled_plugins() -> set[str]:
    """Plugin names (without @marketplace) enabled in Claude Code."""
    settings = _read_json(_claude_dir() / "settings.json") or {}
    return {key.split("@", 1)[0]
            for key, on in (settings.get("enabledPlugins") or {}).items() if on}


def _registered_servers() -> dict[str, set[str]]:
    """Server keys registered outside any plugin, per client."""
    claude = _read_json(_claude_json()) or {}
    vscode = _read_json(_vscode_mcp_json()) or {}
    return {"Claude Code": set((claude.get("mcpServers") or {}).keys()),
            "VS Code": set((vscode.get("servers") or {}).keys())}


# --------------------------------------------------------------------------
# setup (the server does the same by itself; this is the verbose version)
# --------------------------------------------------------------------------

def _setup_copilot() -> None:
    """Register the server for GitHub Copilot in VS Code (minimal toolset)."""
    cfg_path = _vscode_mcp_json()
    if not cfg_path.parent.is_dir():
        _warn("VS Code user folder not found; skipped")
        return
    cfg = _read_json(cfg_path)
    entry = {"type": "stdio", "command": _python(), "args": _server_args(),
             # Copilot caps the tools per request; the engine has ~570, so
             # Copilot gets the two meta-tools (tool_catalog, tool_invoke).
             "env": {"EDA_AGENT_TOOLSET": "minimal"}}
    if cfg is None:
        _warn(f"{cfg_path} is not plain JSON (comments?); add this under \"servers\" by hand:")
        print(json.dumps({SERVER_KEY: entry}, indent=2))
        return
    if cfg_path.exists():
        shutil.copy2(cfg_path, cfg_path.with_suffix(".json.bak"))
    cfg.setdefault("servers", {})[SERVER_KEY] = entry
    cfg_path.write_text(json.dumps(cfg, indent=2) + "\n", encoding="utf-8")
    _ok(f"VS Code Copilot: server 'boardwright' in {cfg_path} (backup .bak)")


def cmd_setup(args) -> int:
    print(f"Boardwright {__version__} setup")
    prepare.ensure_folders()
    _ok(f"data folder {paths.home()}")
    prepare.migrate_legacy(_ok)
    scripts_ok = prepare.deploy_scripts(_ok)
    if not scripts_ok:
        _fail("deploying the Altium scripts failed (see above)")
    if args.copilot:
        _setup_copilot()
    _report_conflicts()
    print()
    print("One step left, in Altium Designer (once per PC):")
    print("  DXP/File > Preferences > Scripting System > Global Projects > Install from file:")
    print(f"    {paths.script_project()}")
    print("  Then File > Run Script > StartMCPServer (or: boardwright relaunch).")
    print("Check everything with: boardwright doctor")
    return 0 if scripts_ok else 1


# --------------------------------------------------------------------------
# remove (undo setup and Boardwright 1.0's registrations; data stays)
# --------------------------------------------------------------------------

def cmd_remove(args) -> int:
    print(f"Boardwright {__version__} remove")
    for skill in OLD_SKILL_LINKS:
        link = _claude_skills_dir() / skill
        if _is_link(link):
            os.rmdir(link)  # the link only, never its target
            _ok(f"skill link {skill} removed")
    if SERVER_KEY in _registered_servers()["Claude Code"]:
        exe = shutil.which("claude")
        if exe:
            r = subprocess.run([exe, "mcp", "remove", SERVER_KEY, "-s", "user"],
                               capture_output=True, text=True)
            if r.returncode == 0:
                _ok("Claude Code: separately registered server removed")
        else:
            _warn("Claude Code CLI not found; remove the 'boardwright' entry "
                  f"from {_claude_json()} by hand")
    cfg_path = _vscode_mcp_json()
    cfg = _read_json(cfg_path)
    if cfg and SERVER_KEY in (cfg.get("servers") or {}):
        shutil.copy2(cfg_path, cfg_path.with_suffix(".json.bak"))
        del cfg["servers"][SERVER_KEY]
        cfg_path.write_text(json.dumps(cfg, indent=2) + "\n", encoding="utf-8")
        _ok("VS Code: server removed (backup .bak)")
    if args.data:
        shutil.rmtree(paths.home(), ignore_errors=True)
        _ok(f"data folder {paths.home()} deleted")
    else:
        print(f"  Data kept in {paths.home()} (verified parts, fab profiles, runs).")
    print("  The plugin itself: /plugin uninstall boardwright in Claude Code.")
    print("  In Altium: Preferences > Scripting System > Global Projects > remove Altium_API.")
    return 0


# --------------------------------------------------------------------------
# doctor
# --------------------------------------------------------------------------

def _report_conflicts() -> int:
    """Warn about anything else that drives Altium or shows the skill twice.
    Returns the number of warnings."""
    warnings = 0
    for client, keys in _registered_servers().items():
        old = sorted(k for k in keys if k in LEGACY_SERVER_KEYS)
        if old:
            _warn(f"{client} also registers {', '.join(old)}: remove it so only "
                  f"one server drives Altium (the last one started wins the bridge)")
            warnings += 1
    if SERVER_KEY in _registered_servers()["Claude Code"] and PLUGIN_NAME in _enabled_plugins():
        _warn("Claude Code registers 'boardwright' twice (plugin + Boardwright 1.0 "
              "setup): run boardwright remove")
        warnings += 1
    for plugin in sorted(set(LEGACY_PLUGINS) & _enabled_plugins()):
        _warn(f"the old plugin '{plugin}' is enabled: /plugin disable {plugin}")
        warnings += 1
    links = [s for s in OLD_SKILL_LINKS if (_claude_skills_dir() / s).exists()]
    if links:
        _warn(f"old skill links {', '.join(links)} in {_claude_skills_dir()}: "
              "run boardwright remove")
        warnings += 1
    return warnings


def cmd_doctor(args) -> int:
    print(f"Boardwright {__version__} (engine {engine.ENGINE_PACKAGE} {engine.version()})")
    bad = 0
    print("Install")
    if paths.install_root():
        _ok(f"bundled runtime {paths.install_root()}")
    else:
        _warn("development environment (not the bundled runtime)")
    for name, p in paths.data_dirs().items():
        (_ok if p.is_dir() else _fail)(f"{name}: {p}")
        bad += 0 if p.is_dir() else 1
    if prepare.scripts_current():
        _ok(f"Altium scripts of this build in {paths.altium_scripts()}")
    elif paths.script_project().is_file():
        _warn(f"Altium scripts are from {prepare.deployed_build() or 'an older build'}; "
              "they are redeployed when the server next starts (or: boardwright setup)")
    else:
        _fail("Altium scripts missing: start the server once, or run boardwright setup")
        bad += 1
    print("Clients")
    if PLUGIN_NAME in _enabled_plugins():
        _ok("Claude Code: Boardwright plugin enabled")
    else:
        _warn("Claude Code: Boardwright plugin not enabled "
              "(/plugin install boardwright@boardwright)")
    if SERVER_KEY in _registered_servers()["VS Code"]:
        _ok("VS Code Copilot: boardwright registered")
    _report_conflicts()
    print("Part-search keys (optional; web search is used without them)")
    for var in KEY_ENV_VARS:
        print(f"  [{'set' if os.environ.get(var) else '--'}]   {var}")
    if args.offline:
        return 1 if bad else 0
    print("Altium link")
    return 1 if (_live_checks() or bad) else 0


# Engine checks that do not apply to Boardwright (other EDA backends).
_SKIPPED_ENGINE_CHECKS = ("easyeda",)


def _boardwright_fix(text: str) -> str:
    """Engine fix hints name engine commands; say the Boardwright one."""
    for engine_cmd in ("python -m eda_agent.server install-scripts --force",
                       "eda-agent install-scripts --force",
                       "eda-agent install-scripts"):
        text = text.replace(f"`{engine_cmd}`", "`boardwright setup`")
    return text.replace("`eda-agent relaunch`", "`boardwright relaunch`")


def _live_checks() -> int:
    """Run the engine's doctor and report it in Boardwright's format.
    Returns the number of critical failures."""
    import contextlib
    import io

    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        engine.run_engine_cli(["doctor", "--json"])
    try:
        report = json.loads(out.getvalue())
    except ValueError:
        print(out.getvalue())
        _fail("engine doctor gave no readable report")
        return 1
    critical = 0
    for check in report.get("checks", []):
        name = check.get("name", "")
        if any(skip in name.lower() for skip in _SKIPPED_ENGINE_CHECKS):
            continue
        status = check.get("status")
        line = name + (f": {check['message']}" if check.get("message") else "")
        if status == "pass":
            _ok(line)
        elif status == "skip":
            print(f"  [--]   {line}")
        elif status == "warn":
            _warn(line)
        else:
            _fail(line)
            if check.get("severity") == "critical":
                critical += 1
        if status in ("warn", "fail") and check.get("fix"):
            print(f"         fix: {_boardwright_fix(check['fix'])}")
    return critical


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------

def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        prog="boardwright",
        description="Boardwright - AI design assistant for Altium Designer.")
    p.add_argument("--version", action="version",
                   version=f"boardwright {__version__} (engine {engine.version()})")
    sub = p.add_subparsers(dest="command")
    sub.add_parser("serve", help="start the MCP server on stdio (default)")
    s = sub.add_parser("setup", help="prepare this PC now (the server also does it)")
    s.add_argument("--copilot", action="store_true",
                   help="also register the server for GitHub Copilot in VS Code")
    d = sub.add_parser("doctor", help="check the install and the Altium link")
    d.add_argument("--offline", action="store_true", help="skip the live Altium check")
    r = sub.add_parser("relaunch", help="start the bridge script in the running Altium")
    r.add_argument("--force", action="store_true", help="even if the bridge answers")
    rm = sub.add_parser("remove", help="remove what setup or Boardwright 1.0 registered")
    rm.add_argument("--data", action="store_true",
                    help="also delete the data folder (verified parts, fab profiles, runs)")
    sub.add_parser("info", help="print versions and folders as JSON")
    e = sub.add_parser("engine", help="run an engine subcommand (advanced)")
    e.add_argument("rest", nargs=argparse.REMAINDER)
    return p


def main(argv: Optional[list[str]] = None) -> int:
    engine.configure()
    args = build_parser().parse_args(argv)
    if args.command in (None, "serve"):
        from . import server
        return server.serve()
    if args.command == "setup":
        return cmd_setup(args)
    if args.command == "doctor":
        return cmd_doctor(args)
    if args.command == "relaunch":
        extra = ["--force"] if args.force else []
        return engine.run_engine_cli(
            ["relaunch", "--prjscr", str(paths.script_project()), *extra])
    if args.command == "remove":
        return cmd_remove(args)
    if args.command == "info":
        from . import server
        print(json.dumps(server.info(), indent=2))
        return 0
    if args.command == "engine":
        return engine.run_engine_cli(args.rest)
    return 2
